def first_n_primes(n: int) -> list[int]:
    """
    Devuelve una lista con los n primeros números primos.

    Args:
        n: Número de primos a devolver.

    Returns:
        Lista con los n primeros números primos.
    """
    if n <= 0:
        return []

    primes = []
    candidate = 2

    while len(primes) < n:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
